export default function sticker({body}){const m=body?.message,chat=m?.chat?.id;if((typeof chat!=='number'&&typeof chat!=='string')||String(chat)==='')throw Error('Telegram message has no chat ID');const name=typeof m?.from?.first_name==='string'&&m.from.first_name?m.from.first_name:'there',s=m?.sticker;if(!s)return {chatId:String(chat),text:`Hi ${name}!
Your message did not contain any sticker.`};if(typeof s.file_id!=='string'||!s.file_id)throw Error('Sticker has no file ID');const set=typeof s.set_name==='string'&&s.set_name?s.set_name:'not available';return {chatId:String(chat),text:`Hi ${name}!
The ID of the sticker is: ${s.file_id}
It is part of the sticker-set: ${set}`}}
